    // set the filter to bone meal, save and load with saveWithFullMetadata and BlockEntity.loadStatic
    // as planter_state_survives_save_and_load does
    helper.assertValueEqual(loaded.fertilizerFilter(), ItemResource.of(Items.BONE_MEAL), "filter loaded");
    // destroyBlock with drops: exactly one ME block item and no bone meal
}

private static void fertilizerTopsUpFromMe(GameTestHelper helper) {
    // meRig, fertilizer block at (2,1,2), 100 bone meal inserted into ME, filter bone meal
    helper.succeedWhen(() -> helper.assertValueEqual(core.fertilizer().available(), 100, "fertilizer stored"));
}
